class RecruitmentIntegrationTest extends AbstractPostgresIntegrationTest {
    @MockitoBean com.google.firebase.FirebaseApp firebase;
    @MockitoBean com.google.firebase.messaging.FirebaseMessaging messaging;
 @Autowired RecruitmentService service;@Autowired CommunityService community;@Autowired UserRepository users;
 @Autowired GroupRepository groups;@Autowired GroupMembershipRepository memberships;@Autowired GroupSettingsRepository settings;
 @Autowired ActivityRepository activities;@Autowired GroupAdmissionService admission;@Autowired GroupPermissionService permissions;
 @Autowired JdbcTemplate db;@Autowired PlatformTransactionManager transactions;@Autowired DomainRealtimeCoordinator realtime;
 @Autowired RealtimeScopeAccess scopes;
 @MockitoBean Clock clock;Instant now;
 @BeforeEach void time(){now=Instant.now();when(clock.instant()).thenAnswer(x->now);when(clock.getZone()).thenReturn(ZoneOffset.UTC);}
 record F(UUID group,UUID activity,UUID owner,UUID member,UUID outsider,UUID other){}
 UUID user(){UUID u=UUID.randomUUID();Instant n=Instant.now();users.save(new UserEntity(u,u+"@r6.test","u"+u.toString().substring(0,8),"R6 QA",UserStatus.ACTIVE,n,n));return u;}
 F fixture(){UUID o=user(),m=user(),x=user(),y=user(),g=UUID.randomUUID(),a=UUID.randomUUID();groups.save(new GroupEntity(g,"R6 approved preview","PRIVATE GROUP DESCRIPTION",null,GroupStatus.ACTIVE,o,now,now));memberships.save(new GroupMembershipEntity(UUID.randomUUID(),g,o,GroupRole.OWNER,GroupMembershipStatus.ACTIVE,now,null));memberships.save(new GroupMembershipEntity(UUID.randomUUID(),g,m,GroupRole.MEMBER,GroupMembershipStatus.ACTIVE,now,null));var s=GroupSettingsEntity.createDefault(g,now);s.update(GroupJoinPolicy.APPROVAL_REQUIRED,false,true,false,ChatHistoryPolicy.FULL_HISTORY,now);settings.save(s);activities.save(new ActivityEntity(a,g,o,"Public chosen title","PRIVATE ACTIVITY DESCRIPTION",ActivityStatus.PLANNING,now.plusSeconds(86400),null,"Asia/Ho_Chi_Minh",null,1,now,now));return new F(g,a,o,m,x,y);}
 RecruitmentDtos.Create request(F f,int count){return new RecruitmentDtos.Create(UUID.randomUUID(),f.group(),f.activity(),"R6 QA Find hikers "+f.group(),CommunityDtos.Visibility.PUBLIC,count,"Ba Vì",List.of("đi bộ","hiking"),now.plusSeconds(86400),now.plusSeconds(3600),List.of());}
 CommunityDtos.Post create(F f,int count){return service.create(f.owner(),request(f,count));}
 @Test void authorizedCreationSnapshotsOnlySafePreviewAndIsIdempotent()throws Exception{F f=fixture();var r=request(f,3);var p=service.create(f.owner(),r);assertEquals(p.id(),service.create(f.owner(),r).id());assertEquals("LOOKING_FOR_MEMBERS",p.postType());var v=service.preview(p.id(),f.outsider());assertEquals("R6 approved preview",v.groupName());assertEquals("Public chosen title",v.activityTitle());String json=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().writeValueAsString(v);assertFalse(json.contains("PRIVATE"));assertFalse(json.contains("memberList"));assertEquals(0,v.approvedCount());assertTrue(v.canRequest());assertThrows(BusinessException.class,()->permissions.requireReadableMembership(f.group(),f.outsider()));}
 @Test void ordinaryMemberAutoJoinGroupAndCrossGroupActivityCannotRecruit(){F f=fixture(),other=fixture();assertThrows(BusinessException.class,()->service.create(f.member(),request(f,1)));var r=request(f,1);assertThrows(BusinessException.class,()->service.create(f.owner(),new RecruitmentDtos.Create(r.clientRequestId(),f.group(),other.activity(),r.caption(),r.visibility(),1,"",List.of(),null,null,List.of())));db.update("UPDATE group_settings SET join_policy='AUTO_JOIN' WHERE group_id=?",f.group());assertThrows(BusinessException.class,()->service.create(f.owner(),request(f,1)));assertFalse(service.options(f.owner()).stream().anyMatch(o->o.groupId().equals(f.group())));}
 @Test void pendingRequestNeverCreatesMembershipAndRetryIsOneCanonicalRequest(){F f=fixture();var p=create(f,2);var one=service.request(p.id(),f.outsider());var two=service.request(p.id(),f.outsider());assertEquals("PENDING",one.requestState());assertEquals(one.requestId(),two.requestId());assertEquals(0,two.approvedCount());assertFalse(member(f.group(),f.outsider()));assertEquals(1,db.queryForObject("SELECT count(*) FROM group_join_requests WHERE group_id=? AND user_id=?",Integer.class,f.group(),f.outsider()));assertEquals(1,service.requests(p.id(),f.owner()).size());}
 boolean member(UUID group,UUID user){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM group_memberships WHERE group_id=? AND user_id=? AND status='ACTIVE')",Boolean.class,group,user));}
 @Test void canonicalApprovalCreatesOneMembershipAndFilledCount(){F f=fixture();var p=create(f,1);var r=service.request(p.id(),f.outsider());assertThrows(BusinessException.class,()->service.resolve(p.id(),r.requestId(),f.member(),true));service.resolve(p.id(),r.requestId(),f.owner(),true);assertTrue(member(f.group(),f.outsider()));var v=service.preview(p.id(),f.outsider());assertEquals("MEMBER",v.requestState());assertEquals(1,v.approvedCount());assertEquals("FILLED",v.status());service.resolve(p.id(),r.requestId(),f.owner(),true);assertEquals(1,db.queryForObject("SELECT count(*) FROM group_memberships WHERE group_id=? AND user_id=? AND status='ACTIVE'",Integer.class,f.group(),f.outsider()));assertEquals(0,db.queryForObject("SELECT count(*) FROM activity_participants WHERE activity_id=? AND user_id=?",Integer.class,f.activity(),f.outsider()));}
 @Test void canonicalControllerApprovalAlsoCannotBypassQuota()throws Exception{F f=fixture();var p=create(f,1);var a=service.request(p.id(),f.outsider());var b=service.request(p.id(),f.other());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var jobs=List.of(pool.submit(()->approve(a.requestId(),f.owner())),pool.submit(()->approve(b.requestId(),f.owner())));int successes=0;for(var job:jobs)if(job.get(15,java.util.concurrent.TimeUnit.SECONDS))successes++;assertEquals(1,successes);}assertEquals(1,service.preview(p.id(),f.owner()).approvedCount());assertEquals(1,(member(f.group(),f.outsider())?1:0)+(member(f.group(),f.other())?1:0));}
 boolean approve(UUID request,UUID owner){try{admission.approveJoinRequest(request,owner);return true;}catch(BusinessException expected){return false;}}
 @Test void closeExpiryDeleteAndActivityCancellationBlockNewRequestsAndApproval(){F f=fixture();var p=create(f,2);var req=service.request(p.id(),f.outsider());service.close(p.id(),f.owner());assertThrows(BusinessException.class,()->service.request(p.id(),f.other()));assertThrows(BusinessException.class,()->admission.approveJoinRequest(req.requestId(),f.owner()));assertFalse(member(f.group(),f.outsider()));var exp=create(f,1);now=now.plusSeconds(3601);assertEquals("EXPIRED",service.preview(exp.id(),f.outsider()).status());assertThrows(BusinessException.class,()->service.request(exp.id(),f.other()));now=now.minusSeconds(3601);var cancelled=create(f,1);db.update("UPDATE activities SET status='CANCELLED' WHERE id=?",f.activity());assertEquals("CLOSED",service.preview(cancelled.id(),f.outsider()).status());assertThrows(BusinessException.class,()->service.request(cancelled.id(),f.other()));var fresh=service.create(f.owner(),new RecruitmentDtos.Create(UUID.randomUUID(),f.group(),null,"Delete",CommunityDtos.Visibility.PUBLIC,1,"",List.of(),null,null,List.of()));community.delete(fresh.id(),f.owner());assertThrows(BusinessException.class,()->service.request(fresh.id(),f.outsider()));}
 @Test void rejectCancelAndAlreadyMemberStatesReuseCanonicalRows(){F f=fixture();var p=create(f,3);var r=service.request(p.id(),f.outsider());service.resolve(p.id(),r.requestId(),f.owner(),false);assertEquals("REJECTED",service.preview(p.id(),f.outsider()).requestState());var next=service.request(p.id(),f.outsider());assertNotEquals(r.requestId(),next.requestId());service.cancel(p.id(),f.outsider());assertEquals("CANCELLED",service.preview(p.id(),f.outsider()).requestState());assertEquals(0,service.preview(p.id(),f.owner()).approvedCount());assertEquals("MEMBER",service.request(p.id(),f.member()).requestState());}
 @Test void blockBanAndVisibilityRemainServerSide(){F f=fixture();var p=create(f,2);db.update("INSERT INTO user_blocks(id,blocker_id,blocked_id) VALUES (?,?,?)",UUID.randomUUID(),f.owner(),f.outsider());assertThrows(BusinessException.class,()->service.preview(p.id(),f.outsider()));db.update("INSERT INTO group_bans(id,group_id,user_id,banned_by) VALUES (?,?,?,?)",UUID.randomUUID(),f.group(),f.other(),f.owner());assertFalse(service.preview(p.id(),f.other()).canRequest());assertThrows(BusinessException.class,()->service.request(p.id(),f.other()));var privatePost=service.create(f.owner(),new RecruitmentDtos.Create(UUID.randomUUID(),f.group(),null,"Group private",CommunityDtos.Visibility.GROUP_ONLY,1,"",List.of(),null,null,List.of()));assertThrows(BusinessException.class,()->service.preview(privatePost.id(),f.other()));assertThrows(BusinessException.class,()->service.requests(p.id(),f.member()));}
 @Test void banAfterPendingAndAuthorRoleLossPreventCanonicalApproval(){F f=fixture();var p=create(f,1);assertTrue(scopes.allowed("review:"+p.id(),f.owner()));assertFalse(scopes.allowed("review:"+p.id(),f.outsider()));assertTrue(scopes.allowed("post:"+p.id(),f.outsider()));var req=service.request(p.id(),f.outsider());db.update("INSERT INTO group_bans(id,group_id,user_id,banned_by) VALUES (?,?,?,?)",UUID.randomUUID(),f.group(),f.outsider(),f.owner());assertThrows(BusinessException.class,()->admission.approveJoinRequest(req.requestId(),f.owner()));assertFalse(member(f.group(),f.outsider()));db.update("UPDATE group_memberships SET role='MEMBER' WHERE group_id=? AND user_id=?",f.group(),f.owner());assertEquals("CLOSED",service.preview(p.id(),f.other()).status());}
 @Test void independentGroupCapacityAndLifetimeCreditsRemainDistinct(){F f=fixture();var p=create(f,1);var req=service.request(p.id(),f.outsider());service.resolve(p.id(),req.requestId(),f.owner(),true);db.update("UPDATE group_memberships SET status='LEFT',ended_at=now() WHERE group_id=? AND user_id=?",f.group(),f.outsider());assertEquals(1,service.preview(p.id(),f.owner()).approvedCount());assertEquals("FILLED",service.preview(p.id(),f.owner()).status());assertThrows(BusinessException.class,()->permissions.requireReadableMembership(f.group(),f.outsider()));F other=fixture();var full=create(other,5);for(int i=0;i<98;i++){UUID u=user();memberships.save(new GroupMembershipEntity(UUID.randomUUID(),other.group(),u,GroupRole.MEMBER,GroupMembershipStatus.ACTIVE,now,null));}assertEquals("FILLED",service.preview(full.id(),other.outsider()).status());assertFalse(service.preview(full.id(),other.outsider()).canRequest());}
 @Test void filtersAndCursorApplyEligibilityBeforeLimit(){F f=fixture();for(int i=0;i<23;i++)create(f,1);var filter=new RecruitmentDtos.Filter(f.group().toString(),"hiking","Ba Vì",now,now.plusSeconds(90000),null);var first=service.discover(f.outsider(),filter);assertEquals(20,first.items().size());create(f,1);var older=service.discover(f.outsider(),new RecruitmentDtos.Filter(f.group().toString(),"hiking","Ba Vì",null,null,first.nextBefore()));assertEquals(3,older.items().size());assertTrue(service.discover(f.outsider(),new RecruitmentDtos.Filter("missing",null,null,null,null,null)).items().isEmpty());service.close(first.items().getFirst().id(),f.owner());assertFalse(service.discover(f.outsider(),filter).items().stream().anyMatch(p->p.id().equals(first.items().getFirst().id())));}
 @Test void rollbackHasNoRequestMembershipOrPostAndCommitUsesSharedSocket()throws Exception{F f=fixture();UUID id=UUID.randomUUID();var r=request(f,1);new TransactionTemplate(transactions).executeWithoutResult(tx->{service.create(f.owner(),new RecruitmentDtos.Create(id,r.groupId(),null,r.caption(),r.visibility(),1,"",List.of(),null,null,List.of()));tx.setRollbackOnly();});assertEquals(0,db.queryForObject("SELECT count(*) FROM community_posts WHERE id=?",Integer.class,id));var p=create(f,2);var socket=mock(org.springframework.web.socket.WebSocketSession.class);when(socket.getId()).thenReturn("r6-"+f.outsider());when(socket.isOpen()).thenReturn(true);realtime.register(socket,f.outsider());realtime.command(socket,"{\"type\":\"SUBSCRIBE_SCOPE\",\"scope\":\"post:"+p.id()+"\"}");clearInvocations(socket);new TransactionTemplate(transactions).executeWithoutResult(tx->{service.request(p.id(),f.outsider());tx.setRollbackOnly();});assertFalse(member(f.group(),f.outsider()));assertEquals(0,db.queryForObject("SELECT count(*) FROM group_join_requests WHERE group_id=?",Integer.class,f.group()));verify(socket,never()).sendMessage(any());service.request(p.id(),f.outsider());verify(socket,timeout(5000).atLeastOnce()).sendMessage(argThat(m->m.getPayload().toString().contains("COMMUNITY_RECRUITMENT_CHANGED")));realtime.unregister(socket);}
}
